        ;
    } else {
        if (spawn_selector == 3) {
            *position = player->presentation.snail_hotspots_world[
                SNAIL_HOTSPOT_BLASTER_LEFT_FIRE];
        } else if (spawn_selector == 2) {
            *position = player->presentation.snail_hotspots_world[
                SNAIL_HOTSPOT_BLASTER_RIGHT_FIRE];
        } else if (spawn_selector == 1) {
            *position = player->presentation.snail_hotspots_world[
                SNAIL_HOTSPOT_BLASTER_TOP_FIRE];
        }

